import itertools
import json

def solve():
    houses = [0, 1, 2, 3]  # 0-based indexing for houses 1-4

    names = ['Eric', 'Alice', 'Peter', 'Arnold']
    smoothies = ['dragonfruit', 'cherry', 'desert', 'watermelon']
    sports = ['soccer', 'tennis', 'basketball', 'swimming']
    cars = ['tesla model 3', 'toyota camry', 'honda civic', 'ford f150']
    flowers = ['daffodils', 'roses', 'lilies', 'carnations']

    solutions = []

    # Helper function
    def pos_of(value_list, value):
        return value_list.index(value)

    # Iterate over sports with constraints:
    for sport_perm in itertools.permutations(sports):
        # Clue 4: The person who loves tennis is in the first house.
        if sport_perm[0] != 'tennis':
            continue

        # Clue 12: The person who loves tennis and the person who loves soccer are next to each other.
        if abs(pos_of(sport_perm, 'tennis') - pos_of(sport_perm, 'soccer')) != 1:
            continue

        idx_basketball = pos_of(sport_perm, 'basketball')

        # Iterate over flowers with constraints:
        for flower_perm in itertools.permutations(flowers):
            # Clue 11: The person who loves basketball is the person who loves the boquet of lilies.
            if flower_perm[idx_basketball] != 'lilies':
                continue

            # Iterate over cars with constraints:
            for car_perm in itertools.permutations(cars):
                idx_toyota = pos_of(car_perm, 'toyota camry')
                idx_civic = pos_of(car_perm, 'honda civic')
                idx_tesla = pos_of(car_perm, 'tesla model 3')

                # Clue 5: The person who owns a Toyota Camry and the person who loves basketball are next to each other.
                if abs(idx_toyota - idx_basketball) != 1:
                    continue

                # Clue 7: The person who owns a Honda Civic is the person who loves a bouquet of daffodils.
                if flower_perm[idx_civic] != 'daffodils':
                    continue

                # Clue 1: The person who owns a Tesla Model 3 is the person who loves the rose bouquet.
                if flower_perm[idx_tesla] != 'roses':
                    continue

                # Iterate over smoothies with constraints:
                for smoothie_perm in itertools.permutations(smoothies):
                    # Clue 9: The Watermelon smoothie lover is not in the first house.
                    if smoothie_perm[0] == 'watermelon':
                        continue

                    # Clue 3: The Desert smoothie lover is the person who owns a Toyota Camry.
                    if smoothie_perm[idx_toyota] != 'desert':
                        continue

                    # Clue 10: The person who owns a Honda Civic is somewhere to the right of the Desert smoothie lover.
                    if idx_civic <= pos_of(smoothie_perm, 'desert'):
                        continue

                    # Iterate over names with constraints:
                    for name_perm in itertools.permutations(names):
                        # Clue 6: Arnold is the person who loves basketball.
                        if name_perm[idx_basketball] != 'Arnold':
                            continue

                        # Clue 8: Eric is the person who loves the rose bouquet.
                        if name_perm[pos_of(flower_perm, 'roses')] != 'Eric':
                            continue

                        # Clue 2: Peter is the Dragonfruit smoothie lover.
                        if name_perm[pos_of(smoothie_perm, 'dragonfruit')] != 'Peter':
                            continue

                        # All constraints satisfied; record solution.
                        solutions.append({
                            'Name': list(name_perm),
                            'favorite smoothie': list(smoothie_perm),
                            'favorite sports': list(sport_perm),
                            'car models': list(car_perm),
                            'favorite flower': list(flower_perm),
                        })

    # Expect exactly one solution
    if not solutions:
        raise RuntimeError("No solution found.")
    if len(solutions) > 1:
        # If multiple, pick the first but this should not happen for a well-posed puzzle
        solution = solutions[0]
    else:
        solution = solutions[0]

    header = ["House", "Name", "favorite smoothie", "favorite sports", "car models", "favorite flower"]
    rows = []
    for i in range(4):
        rows.append([
            str(i + 1),
            solution["Name"][i],
            solution["favorite smoothie"][i],
            solution["favorite sports"][i],
            solution["car models"][i],
            solution["favorite flower"][i],
        ])

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    print(json.dumps(output, ensure_ascii=False, indent=2))

if __name__ == "__main__":
    solve()
